import { observer } from 'mobx-react-lite';
import React, { useEffect } from 'react';
import { useLocation, useParams} from 'react-router-dom/cjs/react-router-dom';
import { useContext } from 'react';
import { Context } from '../index';
import { getBasket , delFromBasket} from '../http/basketAPI';
import { Button, Card, Col, Container, Row } from 'react-bootstrap'
import { getOneOrder } from '../http/orderAPI';

const OrderPage = () => {
  const {order} = useContext(Context)
  const id = useParams()
  useEffect(()=>{
    getOneOrder(id.id).then(data => order.setOneOrder(data))
  }, [])

  return (
    <Container className="min-vh-100 d-flex flex-sm-column justify-content-center align-items-center mt-3">
      {console.log(order.oneOrder)}
      <div>{order.oneOrder.id}</div>
    </Container>
  );
};

export default OrderPage;
